with recent_products as (select * from products where supplier_id is not null and (year(launch_date) >= 2023 or cost > 180)), category_group_summary as (select case when category in ('Books', 'Home') then 'tier_1' else 'other' end as category_group, case when year(launch_date) < 2024 then 'before_2024' when year(launch_date) = 2024 then '2024' else 'after_2024' end as launch_cohort, avg(stock_qty) as avg_stock_qty from recent_products group by case when category in ('Books', 'Home') then 'tier_1' else 'other' end, case when year(launch_date) < 2024 then 'before_2024' when year(launch_date) = 2024 then '2024' else 'after_2024' end) select * from category_group_summary order by category_group desc;
